import{_ as e,o as t,c as s,a2 as l}from"./chunks/framework.DQbZ8cc1.js";const b=JSON.parse('{"title":"Install with Release Package","description":"","frontmatter":{},"headers":[],"relativePath":"docs/installation/release.md","filePath":"docs/installation/release.md"}'),i={name:"docs/installation/release.md"};function n(o,a,r,d,c,p){return t(),s("div",null,[...a[0]||(a[0]=[l(`<h1 id="install-with-release-package" tabindex="-1">Install with Release Package <a class="header-anchor" href="#install-with-release-package" aria-label="Permalink to “Install with Release Package”">​</a></h1><p>The release package is the recommended installation method when you do not want to use Docker.</p><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to “Requirements”">​</a></h2><ul><li>OS: Windows / macOS / Linux</li><li>Memory: 2GB+ recommended</li><li>Database: <ul><li>SQLite for local trial and small sites</li><li>MySQL 8+ recommended for production</li></ul></li></ul><h2 id="download" tabindex="-1">Download <a class="header-anchor" href="#download" aria-label="Permalink to “Download”">​</a></h2><p>Releases: <a href="https://github.com/mlogclub/bbs-go/releases/latest" target="_blank" rel="noreferrer">https://github.com/mlogclub/bbs-go/releases/latest</a></p><table tabindex="0"><thead><tr><th>Platform</th><th>File</th></tr></thead><tbody><tr><td>Windows</td><td><code>bbs-go-windows-x86_64.zip</code></td></tr><tr><td>macOS Intel</td><td><code>bbs-go-macos-amd64.zip</code></td></tr><tr><td>macOS Apple Silicon</td><td><code>bbs-go-macos-arm64.zip</code></td></tr><tr><td>Linux 64-bit</td><td><code>bbs-go-linux-amd64.zip</code></td></tr><tr><td>Linux 32-bit</td><td><code>bbs-go-linux-386.zip</code></td></tr></tbody></table><h2 id="package-layout" tabindex="-1">Package Layout <a class="header-anchor" href="#package-layout" aria-label="Permalink to “Package Layout”">​</a></h2><p>After extracting a release package, the directory includes the executable and built-in resources:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;release-root&gt;/</span></span>
<span class="line"><span>├── bbs-go</span></span>
<span class="line"><span>├── res/</span></span>
<span class="line"><span>├── locales/</span></span>
<span class="line"><span>└── site/</span></span></code></pre></div><h2 id="start-bbs-go" tabindex="-1">Start BBS-GO <a class="header-anchor" href="#start-bbs-go" aria-label="Permalink to “Start BBS-GO”">​</a></h2><p>Run from the extracted directory:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Linux/macOS</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bbs-go</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Windows</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bbs-go.exe</span></span></code></pre></div><p>Default port: <code>8082</code>.</p><h2 id="first-time-installation" tabindex="-1">First-Time Installation <a class="header-anchor" href="#first-time-installation" aria-label="Permalink to “First-Time Installation”">​</a></h2><p>Open:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://localhost:8082/install</span></span></code></pre></div><p>Installer steps:</p><ol><li>Select language (<code>en-US</code> / <code>zh-CN</code>).</li><li>Select database.</li><li>Fill site information.</li><li>Create admin account.</li><li>Complete installation.</li></ol><p>For local trial, select SQLite. For production, use MySQL 8+.</p><h2 id="access-urls" tabindex="-1">Access URLs <a class="header-anchor" href="#access-urls" aria-label="Permalink to “Access URLs”">​</a></h2><ul><li>Site: <code>http://localhost:8082/</code></li><li>Admin dashboard: <code>http://localhost:8082/dashboard</code></li><li>API: <code>http://localhost:8082/api/*</code></li></ul><h2 id="common-issues" tabindex="-1">Common Issues <a class="header-anchor" href="#common-issues" aria-label="Permalink to “Common Issues”">​</a></h2><h3 id="port-already-in-use" tabindex="-1">Port Already in Use <a class="header-anchor" href="#port-already-in-use" aria-label="Permalink to “Port Already in Use”">​</a></h3><p>Change <code>Port</code> in <code>bbs-go.yaml</code> or stop the conflicting process.</p><h3 id="database-connection-failed" tabindex="-1">Database Connection Failed <a class="header-anchor" href="#database-connection-failed" aria-label="Permalink to “Database Connection Failed”">​</a></h3><ul><li>MySQL: verify host, port, username, password, and database name.</li><li>SQLite: choose SQLite in the installer. No manual database setup is required.</li></ul><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to “Next Steps”">​</a></h2><ul><li><a href="./production.html">Production Deployment</a></li><li><a href="./docker.html">Docker Deployment</a></li><li><a href="./server/google-login.html">Google Login Setup</a></li></ul>`,29)])])}const m=e(i,[["render",n]]);export{b as __pageData,m as default};
